// Generated helper functions
// This file contains assertion and utility functions
// Includes both created functions and functions from the helper pool

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <assert.h>
#include <string.h>
#include <math.h>
#include "../../../include/bst/header.h"

// ========== Searched From Pool - Assertion Operations ==========

// Function: assert_array_equal (from helper pool)
void assert_array_equal(const int *actual, const int *expected, int size)
{
    /*
    Assert that two arrays are equal.
    */
    assert(actual != NULL && expected != NULL);
    assert(size > 0);
    for (int i = 0; i < size; ++i)
    {
        assert(actual[i] == expected[i]);
    }
}

// ========== Created - Assertion Operations ==========

// Prototype for helper_tree_to_inorder_array
int* helper_tree_to_inorder_array(struct node *root, int size);

// Asserts that the inorder traversal of the given tree matches the expected array.
void assert_tree_inorder_equal(struct node *root, const int *expected, int size) {
    int *actual = helper_tree_to_inorder_array(root, size);
    assert_array_equal(actual, expected, size);
    free(actual);
}

// ========== Created - Utility Operations ==========

// Builds a binary search tree from an array of values using insert.
struct node* helper_build_tree(int *values, int size) {
    struct node *root = NULL;
    for (int i = 0; i < size; ++i) {
        root = insert(root, values[i]);
    }
    return root;
}

// Converts the tree to an inorder array of keys. The size must be provided and match the number of nodes.
static void inorder_fill(struct node *root, int *arr, int *idx) {
    if (root) {
        inorder_fill(root->left, arr, idx);
        arr[(*idx)++] = root->key;
        inorder_fill(root->right, arr, idx);
    }
}
int* helper_tree_to_inorder_array(struct node *root, int size) {
    int *arr = (int*)malloc(sizeof(int) * size);
    int idx = 0;
    inorder_fill(root, arr, &idx);
    return arr;
}

// Frees all nodes in the binary search tree.
void helper_free_tree(struct node *root) {
    if (root) {
        helper_free_tree(root->left);
        helper_free_tree(root->right);
        free(root);
    }
}


